% Problem-section file following ../_template.tex.
\section{Finite-alphabet nonsignalling simulation of entangled qubits}
\label{sec:problem-29}

\paragraph{Problem.}
For every partially entangled two-qubit pure state, does some fixed
finite-alphabet nonsignalling resource give an exact noncommunicating
simulation of all local projective measurements?  Fix
\begin{equation}
  \lvert\psi_\theta\rangle
  =\cos\theta\,\lvert00\rangle+\sin\theta\,\lvert11\rangle,
  \qquad 0<\theta<\frac{\pi}{4}.
  \label{eq:p29-partially-entangled-state}
\end{equation}
The target correlations for Bloch directions
$\mathbf x,\mathbf y\in S^2$ are
\begin{equation}
  P_\theta(a,b\mid\mathbf x,\mathbf y)
  =\operatorname{Tr}\!\left[
    \lvert\psi_\theta\rangle\!\langle\psi_\theta\rvert
    \bigl(M_{a\mid\mathbf x}\otimes M_{b\mid\mathbf y}\bigr)
    \right],
  \qquad a,b\in\{0,1\},
  \label{eq:p29-target-correlation}
\end{equation}
where $M_{a\mid\mathbf x}=(I+(-1)^a\mathbf x\cdot\boldsymbol\sigma)/2$
and similarly for Bob.  For each $\theta$ in
Eq.~\eqref{eq:p29-partially-entangled-state}, one may choose a nonsignalling
box $R(u,v\mid s,t)$ with finite input and output alphabets and a finite
number of copies of it.  The box, the number of copies, and the local wiring
may depend on $\theta$ but not on $\mathbf x$ or $\mathbf y$, and the wiring
may use unlimited shared randomness but no communication.  It must reproduce
Eq.~\eqref{eq:p29-target-correlation} exactly.

\subsection*{Status}

Unsolved

\subsection*{Source}

Gisin explicitly poses finite-alphabet nonsignalling simulation, while
Brunner et al. isolate the same finiteness gap after giving a continuous-input
construction \sourcecite{ref:p29-gisin}{Gis09},
\sourcecite{ref:p29-brunner-pra}{BGPS08}.

\subsection*{Progress}

\begin{itemize}
  \item Gisin posed the existence of a finite-input, finite-output
  nonsignalling resource for this task
  \sourcecite{ref:p29-gisin}{Gis09}.

  \item At the excluded maximally entangled endpoint $\theta=\pi/4$, one
  finite-alphabet PR box and shared randomness reproduce all local projective
  measurements exactly \sourcecite{ref:p29-cerf}{CGMP05}.

  \item Brunner, Gisin, Popescu, and Scarani constructed an exact simulation
  for every state in Eq.~\eqref{eq:p29-partially-entangled-state}, but their
  protocol uses a continuous-input millionaire box that compares real
  parameters.  They explicitly leave replacement by finite-input resources
  open \sourcecite{ref:p29-brunner-pra}{BGPS08}.

  \item Some finite measurement sets obtained from partially entangled states
  cannot be simulated with a single PR box.  This rules out one particular
  resource budget, not all finite-alphabet resources or all finite numbers of
  uses \sourcecite{ref:p29-brunner-njp}{BGS05}.
\end{itemize}

